export class RxDemo {
  private sub?: Subscription;
  ticketPrice: number = 0;

  startListening(price$: Observable<number>): void {
    this.sub = price$.subscribe((val) => {
      this.ticketPrice = val;
    });
  }

  stopListening(): void {
    this.sub?.unsubscribe();
  }
}

